import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import java.util.*;

public final class StarterDeck100DamageReactionTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static String id(int n){return StarterDeck100PokemonTest.id(n);}
    static void check(boolean ok,String why){StarterDeck100PokemonTest.check(ok,why);}
    public static void main(String[] args){guts();noGuts();ownDamage();slate();pressure();System.out.println("StarterDeck100DamageReactionTest passed: actual SD100 Guts and Spiteful Slate, both coin outcomes, own damage, damage/counter distinction, VMAX immunity and lethal counterattack");}
    static void guts(){boolean heads=false,tails=false;for(int seed=0;seed<100&&!(heads&&tails);seed++){
        var m=StarterDeck100PokemonTest.gameSeed(220,349,seed);var victim=m.activePokemonView(A).pokemonId();m.placeDamageCountersByEffect(A,A,victim,12);m.endTurn(A);StarterDeck100GuardTest.prepareOpponent(m,349,0);int rng=m.randomTranscript().size();m.attack(B,"double-dip-fangs");check(m.randomTranscript().size()==rng+1,"Guts must flip exactly once");boolean survived=m.phase()==MatchPhase.TURN;heads|=survived;tails|=!survived;StarterDeck100CombatTest.settleKnockouts(m);check(m.publicView().get(B).prizeCount()==(survived?6:5),"survival awarded prizes or Evolution got extra prize");if(survived)check(m.activePokemonView(A).pokemonId().equals(victim)&&m.activePokemonView(A).damage()==130,"Guts remaining HP");}check(heads&&tails,"both Guts outcomes not covered");}
    static void noGuts(){for(int mode=0;mode<4;mode++){
        var m=StarterDeck100PokemonTest.game(220);var victim=m.activePokemonView(A).pokemonId();int rng;
        if(mode==0){rng=m.randomTranscript().size();m.placeDamageCountersByEffect(A,A,victim,14);}
        else if(mode==1){rng=m.randomTranscript().size();m.knockOutPokemonByEffect(A,A,victim);}
        else if(mode==2){m.placeDamageCountersByEffect(A,A,victim,13);m.applySpecialConditionByEffect(A,A,SpecialCondition.POISONED);rng=m.randomTranscript().size();m.endTurn(A);}
        else {m.placeDamageCountersByEffect(A,A,victim,13);m.disableAbilityEffectsByEffect(A,A,victim);m.endTurn(A);StarterDeck100GuardTest.prepareOpponent(m,1,0);rng=m.randomTranscript().size();m.attack(B,"leaf-drain");}
        check(m.randomTranscript().size()==rng,"Guts flipped for counters/directKO/poison/disabled");StarterDeck100CombatTest.settleKnockouts(m);check(!m.activePokemonView(A).pokemonId().equals(victim),"ineligible Guts saved source");}}
    static void ownDamage(){var guts=StarterDeck100CombatTest.COMBAT.pokemon(id(220)).orElseThrow().abilities().getFirst();for(String extra:List.of(",\"selfDamage\":500",",\"triggers\":[{\"trigger\":\"AFTER_ATTACK\",\"effects\":[{\"type\":\"self_damage\",\"target\":\"SELF\",\"amount\":500}]}]",",\"triggers\":[{\"trigger\":\"AFTER_ATTACK\",\"effects\":[{\"type\":\"bench_damage\",\"target\":\"OWN_BENCH\",\"amount\":500}]}]")){
        boolean heads=false,tails=false;for(int seed=0;seed<40&&!(heads&&tails);seed++) {var m=SharedUsageLimitTest.attackFixture(seed,List.of(guts),List.of(DamageTriggeredAbilityTest.attack(0,extra)));var actor=m.currentPlayer();int rng=m.randomTranscript().size();m.attack(actor,"hit");check(m.randomTranscript().size()==rng+1,"own attack damage did not trigger Guts");boolean survived=m.phase()==MatchPhase.TURN;heads|=survived;tails|=!survived;if(survived){var target=extra.contains("OWN_BENCH")?m.benchPokemonView(actor).getFirst():m.activePokemonView(actor);check(target.damage()==290,"own damage survival wrong HP");}}check(heads&&tails,"own damage outcomes");}
        var react=DamageTriggeredAbilityTest.ability("opponent-only",false,false,false,DamageTriggeredAbilityTest.DRAW);var m=DamageTriggeredAbilityTest.fixture(DamageTriggeredAbilityTest.attack(0,",\"triggers\":[{\"trigger\":\"AFTER_ATTACK\",\"effects\":[{\"type\":\"bench_damage\",\"target\":\"OWN_BENCH\",\"amount\":10}]}]"),react);var actor=m.currentPlayer();int hand=m.privateView(actor).hand().size();m.attack(actor,"hit");check(m.privateView(actor).hand().size()==hand,"own Bench damage triggered opponent-only event");}
    static void slate(){for(int attacker:List.of(1,150,310))for(boolean disabled:List.of(false,true)){
        var m=StarterDeck100PokemonTest.game(231,attacker);if(disabled)m.disableAbilityEffectsByEffect(A,A,m.activePokemonView(A).pokemonId());m.endTurn(A);StarterDeck100GuardTest.attackOpponent(m,attacker,0);int reflected=!disabled&&attacker==150?m.lastAttack().finalDamage():0;check(m.activePokemonView(B).damage()==reflected,"VMAX/damage/ability immunity filter "+attacker);StarterDeck100CombatTest.settleKnockouts(m);}
        var m=StarterDeck100PokemonTest.game(231,150);m.endTurn(A);StarterDeck100GuardTest.prepareOpponent(m,150,0);m.placeDamageCountersByEffect(B,B,m.activePokemonView(B).pokemonId(),20);m.attack(B,"max-shock");check(m.phase()==MatchPhase.PRIZE_SELECTION,"lethal VMAX counterattack not simultaneous KO");StarterDeck100CombatTest.settleKnockouts(m);check(m.publicView().get(A).prizeCount()==3&&m.publicView().get(B).prizeCount()==5,"simultaneous KO wrong prizes");
        var counter=StarterDeck100PokemonTest.game(231,150);counter.placeDamageCountersByEffect(A,A,counter.activePokemonView(A).pokemonId(),12);check(counter.activePokemonView(B).damage()==0,"counters triggered slate");
        var bench=StarterDeck100PokemonTest.game(231,104);var host=StarterDeck100EntryTest.evolveBench(bench,231);bench.disableAbilityEffectsByEffect(A,A,bench.activePokemonView(A).pokemonId());bench.endTurn(A);StarterDeck100GuardTest.attackOpponent(bench,104,0);StarterDeck100GuardTest.benchChoice(bench,B,host);check(bench.activePokemonView(B).damage()==0,"Bench damage triggered Active-only slate");}
    static void pressure(){var m=StarterDeck100PokemonTest.game(231,1,"sm1_en_136");var energy=m.privateView(A).deck().stream().filter(c->c.definitionId().equals("sm1_en_136")).findFirst().orElseThrow();m.attachEnergyByEffect(A,A,EffectSourceZone.DECK,energy.instanceId(),B,m.activePokemonView(B).pokemonId());StarterDeck100PokemonTest.attack(m,0);check(m.lastAttack().finalDamage()==100,"Energy Press counted cards instead of Energy units");}
}
